  FT["PH-H2793"] = {"id":"PH-H2793","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1961/ra_3316_1961.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"进一步修订第1900号共和国法（即公共工程拨款法，经修正）的法案","en":"An Act Further Amending Republic Act Numbered Nineteen Hundred, Entitled “An Act Appropriating Funds for Public Works,” as Amended","orig":"An Act Further Amending Republic Act Numbered Nineteen Hundred, Entitled “An Act Appropriating Funds for Public Works,” as Amended"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 3316","issuingBody":"Congress of the Philippines","promulgatedDate":"1961-06-18","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1961/ra_3316_1961.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2793-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Item (f -1), page 352, Group II, for the Province of Negros Oriental, Section two, entitled \"Short Term Projects,\" of Republic Act Numbered Nineteen hundred, as amended by Republic Act Numbered Twenty-eight hundred fifty-eight, is hereby further amended to read as follows:\n\"(f-1) Larena-Basac-Maria Road Repair and/or improvement ₱10,000.00\""}},{"id":"PH-H2793-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1961."}}],"pack":"ph-p39","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Further Amending Republic Act Numbered Nineteen Hundred, Entitled “An Act Appropriating Funds for Public Works,” as Amended","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2794"] = {"id":"PH-H2794","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1961/ra_3317_1961.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"在伊莎贝拉省Ilagan市镇伊莎贝拉省立医院设立、维护与运营护理与助产学校并授权为此拨款的法案","en":"An Act to Establish, Maintain and Operate a School of Nursing and Midwifery in the Isabela Provincial Hospital Located in the Municipality of Ilagan, Province of Isabela, and to Authorize the Appropriation of Funds Therefor","orig":"An Act to Establish, Maintain and Operate a School of Nursing and Midwifery in the Isabela Provincial Hospital Located in the Municipality of Ilagan, Province of Isabela, and to Authorize the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["education","health"],"docNumber":"Republic Act No. 3317","issuingBody":"Congress of the Philippines","promulgatedDate":"1961-06-18","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1961/ra_3317_1961.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2794-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established a school of nursing and midwifery in the Isabela Provincial Hospital located in the Municipality of Ilagan, Province of Isabela. The establishment, maintenance and operation of said school of nursing and midwifery shall be under the control and management of the Director of the said Isabela Provincial Hospital, subject to the executive supervision of the Director of Medical Services."}},{"id":"PH-H2794-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of two hundred thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the establishment, maintenance and operation of the school of nursing and midwifery under this Act, which shall be disbursed by the Director of the Isabela Provincial Hospital, subject to the approval of the Director of Medical Services."}},{"id":"PH-H2794-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1961."}}],"pack":"ph-p39","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Establish, Maintain and Operate a School of Nursing and Midwifery in the Isabela Provincial Hospital Located in the Municipality of Ilagan, Province of Isabela, and to Authorize the Appropriation of Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2795"] = {"id":"PH-H2795","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1961/ra_3318_1961.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"重新划拨第1411号共和国法项下用于购置扩建西内格罗斯省Pulupandan市镇Palaca村学校校址的增补场地的5000比索的法案","en":"An Act Reappropriating the Sum of Five Thousand Pesos Appropriated Under Republic Act Numbered Fourteen Hundred Eleven for the Purchase of Additional Site to Expand the School Lot of the Barrio School of Palaca, Municipality of Pulupandan, Province of Negros Occidental","orig":"An Act Reappropriating the Sum of Five Thousand Pesos Appropriated Under Republic Act Numbered Fourteen Hundred Eleven for the Purchase of Additional Site to Expand the School Lot of the Barrio School of Palaca, Municipality of Pulupandan, Province of Negros Occidental"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 3318","issuingBody":"Congress of the Philippines","promulgatedDate":"1961-06-18","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1961/ra_3318_1961.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2795-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sum of five thousand pesos appropriated under item 20, page 527, group II, subparagraph ai, for the Province of Negros Occidental, Section three of Republic Act Numbered Fourteen hundred eleven, for the construction of an additional room for the Palaca Barrio School building, Barrio Palaca, Municipality of Pulupandan, is hereby reappropriated for the purchase of additional site to expand the school lot of the said barrio school."}},{"id":"PH-H2795-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1961."}}],"pack":"ph-p39","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Reappropriating the Sum of Five Thousand Pesos Appropriated Under Republic Act Numbered Fourteen Hundred Eleven for the Purchase of Additional Site to Expand the School Lot of the Barrio School of Palaca, Municipality of Pulupandan, Province of Negros Occidental","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2796"] = {"id":"PH-H2796","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1961/ra_3319_1961.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Echague市","en":"An Act Declaring Regular and Official the Barrios of Cebu, Pabel, Gud, Victoria, Gomez, Villaflor, Malibago, Babaran, Sta. Cruz, Rumang-Say, San Felipe, Sta. Monica, Ramos, Maligaya, Castillo, San Fabian, Pangal Norte, and Villa Victoria in the Municipality of Echague, Province of Isabela","orig":"An Act Declaring Regular and Official the Barrios of Cebu, Pabel, Gud, Victoria, Gomez, Villaflor, Malibago, Babaran, Sta. Cruz, Rumang-Say, San Felipe, Sta. Monica, Ramos, Maligaya, Castillo, San Fabian, Pangal Norte, and Villa Victoria in the Municipality of Echague, Province of Isabela"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 3319","issuingBody":"Congress of the Philippines","promulgatedDate":"1961-06-18","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1961/ra_3319_1961.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2796-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The barrios of Cebu, Pabel, Gud, Victoria, Gomez, Villaflor, Malibago, Babaran, Sta. Cruz, Rumangsay, San Felipe, Sta. Monica, Ramos, Maligaya, Castillo, San Fabian, Pangal Norte, and Villa Victoria in the Municipality of Echague, Province of Isabela, are hereby declared regular and official barrios."}},{"id":"PH-H2796-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1961."}}],"pack":"ph-p39"};
  FT["PH-H2797"] = {"id":"PH-H2797","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1961/ra_3320_1961.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"在伊莎贝拉省设立Ramon市镇的法案","en":"An Act Creating the Municipality of Ramon in the Province of Isabela","orig":"An Act Creating the Municipality of Ramon in the Province of Isabela"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 3320","issuingBody":"Congress of the Philippines","promulgatedDate":"1961-06-18","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1961/ra_3320_1961.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2797-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The barrios of Bugallon, Burgos, San Miguel, San Sebastian, Raniag and Pagrang-ayan are separated from the Municipality of Santiago, and the barrios of Oscariz, Nagbacalan and Bantug Petinez are separated from the Municipality of San Mateo, all in the Province of Isabela, and constituted into a new and separate municipality of said province to be known as the Municipality of Ramon, with the seat of government at the present site of the barrio of Burgos."}},{"id":"PH-H2797-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon the election of the new municipal officials in the general election for local officials in November of nineteen hundred sixty-three.\nApproved: June 18, 1961."}}],"pack":"ph-p39","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating the Municipality of Ramon in the Province of Isabela","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2798"] = {"id":"PH-H2798","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1961/ra_3321_1961.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"确定北伊罗戈省Carasi市镇区边界的法案","en":"An Act Fixing the Boundaries of the Municipal District of Carasi, Province of Ilocos Norte","orig":"An Act Fixing the Boundaries of the Municipal District of Carasi, Province of Ilocos Norte"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 3321","issuingBody":"Congress of the Philippines","promulgatedDate":"1961-06-18","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1961/ra_3321_1961.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2798-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The area comprising the Municipal District of Carasi, Province of Ilocos Norte, shall be bounded as follows:\nBeginning at Corner 1, which is N 60° E, 6,000 meters from B.L.L.M. No. 1 of the Municipality of Solsona, Province of Ilocos Norte; thence N 20° W, 8,000 meters to Corner 2; thence N 75° E, 13,850 meters to Corner 3; thence S 42° E, 3,500 meters to Corner 4; thence S 67° E, 2,300 meters to Corner 5; thence S 70° W, 2,050 meter to Corner 6; thence S 80° W, 2,000 meters to Corner 7; thence S 74° W, 6,150 meters to Corner 8; thence S 46° W, 6,750 meters to the point of beginning, containing an area of 8,296.7 hectares, more or less."}},{"id":"PH-H2798-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of ten thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the boundary survey thereof."}},{"id":"PH-H2798-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1961."}}],"pack":"ph-p39","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Fixing the Boundaries of the Municipal District of Carasi, Province of Ilocos Norte","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2799"] = {"id":"PH-H2799","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1961/ra_3322_1961.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Baler市","en":"An Act Creating a Branch Office of the Register of Deeds of the Province of Quezon, with Permanent Station at the Municipality of Baler, Subprovince of Aurora, Same Province, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Creating a Branch Office of the Register of Deeds of the Province of Quezon, with Permanent Station at the Municipality of Baler, Subprovince of Aurora, Same Province, and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 3322","issuingBody":"Congress of the Philippines","promulgatedDate":"1961-06-18","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1961/ra_3322_1961.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2799-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby created a branch office of the Register of Deeds of the Province of Quezon, with permanent station at the Municipality of Baler, Subprovince of Aurora, same province, which shall perform all the duties and functions of the register of deeds for the following municipalities: Baler, Casiguran, Dipaculao, Maria Aurora and Dingalan."}},{"id":"PH-H2799-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"To carry out the provision of this Act, there is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, the sum of eight thousand two hundred eighty pesos which shall be spent for the following:\n(a) Deputy Register of Deeds ₱2,400.00\n(b) One Clerk 1,440.00\n(c) One janitor messenger 1,440.00\n(d) Sundry expenses 3,000.00 ₱8,280.00 Such sums as may be necessary for the same purpose in subsequent years shall be included in the annual General Appropriation Acts."}},{"id":"PH-H2799-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1961."}}],"pack":"ph-p39"};
  FT["PH-H2800"] = {"id":"PH-H2800","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1961/ra_3323_1961.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"将伊莎贝拉省Cauayan中学改设为Cauayan农村中学的法案","en":"An Act to Convert the Cauayan High School in the Province of Isabela into a Rural High School, to be Known as the Cauayan Rural High School","orig":"An Act to Convert the Cauayan High School in the Province of Isabela into a Rural High School, to be Known as the Cauayan Rural High School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 3323","issuingBody":"Congress of the Philippines","promulgatedDate":"1961-06-18","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1961/ra_3323_1961.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2800-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Cauayan High School in the Province of Isabela is hereby converted into a rural high school to be known as the Cauayan Rural High School."}},{"id":"PH-H2800-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of seventy-five thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the operation and maintenance of said school for the school year nineteen hundred sixty-two. Thereafter, the necessary sum for said purpose shall be included in the annual General Appropriation Acts."}},{"id":"PH-H2800-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1961."}}],"pack":"ph-p39","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Convert the Cauayan High School in the Province of Isabela into a Rural High School, to be Known as the Cauayan Rural High School","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2801"] = {"id":"PH-H2801","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1961/ra_3324_1961.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"为北卡加延设立契约登记副专员职位的法案","en":"An Act Creating a Position of Deputy Register of Deeds for Northern Cagayan","orig":"An Act Creating a Position of Deputy Register of Deeds for Northern Cagayan"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 3324","issuingBody":"Congress of the Philippines","promulgatedDate":"1961-06-18","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1961/ra_3324_1961.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2801-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby created a position of deputy of register of deeds for Northern Cagayan."}},{"id":"PH-H2801-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Deputy Register of Deeds for Northern Cagayan shall hold office in the Municipality of Aparri and shall record and sign exclusively registerable titles, documents and other instruments relative to lands situated in the Municipalities of Aparri, Camalaniugan, Lallo, Gattaran, Lasam, Allacapan, Buguey, Gonzaga, Abulug, Claveria, Ballesteros, Pamplona, Sanchez Mira, Calayan, Langangan and Sta. Ana: Provided, That he shall be under the administrative supervision of the Register of Deeds of Cagayan."}},{"id":"PH-H2801-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Deputy Register of Deeds for the Province of Cagayan at the approval of this Act shall be assigned to take over all the duties and functions of the Deputy of Register of Deeds for Northern Cagayan."}},{"id":"PH-H2801-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1961."}}],"pack":"ph-p39","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating a Position of Deputy Register of Deeds for Northern Cagayan","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
