  FT["PH-H2808"] = {"id":"PH-H2808","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1961/ra_3331_1961.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Roxas市","en":"An Act Creating Certain Barrios in the Municipality of Roxas, Province of Palawan","orig":"An Act Creating Certain Barrios in the Municipality of Roxas, Province of Palawan"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 3331","issuingBody":"Congress of the Philippines","promulgatedDate":"1961-06-18","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1961/ra_3331_1961.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2808-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitios of San Miguel, Arasan, New Cuyo, Salvacion and Narra in the Municipality of Roxas, Province of Palawan, are converted into barrios of said municipality, to be known as the barrios of San Miguel, Arasan, New Cuyo, Salvacion and Narra, respectively."}},{"id":"PH-H2808-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1961."}}],"pack":"ph-p39"};
  FT["PH-H2809"] = {"id":"PH-H2809","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1961/ra_3332_1961.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"为Cotabato市增设两名助理检察官，为此修订Cotabato市宪章第23条的法案","en":"An Act to Provide Two Assistant Attorneys for the City of Cotabato, Amending for the Purpose Section Twenty-Three of the Charter of the City of Cotabato","orig":"An Act to Provide Two Assistant Attorneys for the City of Cotabato, Amending for the Purpose Section Twenty-Three of the Charter of the City of Cotabato"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 3332","issuingBody":"Congress of the Philippines","promulgatedDate":"1961-06-18","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1961/ra_3332_1961.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2809-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The first paragraph of Section twenty-three of Republic Act Numbered Twenty-three hundred sixty-four, otherwise known as the \"Charter of the City of Cotabato,\" is amended to read as follows:\n\"Sec. 23. The city attorney His compensation, powers and duties. The provisions of Commonwealth Act Numbered Four hundred nine to the contrary notwithstanding, the city shall have an attorney who shall be the chief legal adviser of the city. He shall have two assistant attorneys with compensation at the rate of four thousand two hundred pesos and three thousand seven hundred twenty pesos, respectively per annum. Said assistant attorneys shall be appointed by the President of the Philippines with the consent of the Commission on Appointments. The city attorney shall have the following powers and duties.\""}},{"id":"PH-H2809-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nEnacted, without Executive approval, June 18, 1961."}}],"pack":"ph-p39","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Provide Two Assistant Attorneys for the City of Cotabato, Amending for the Purpose Section Twenty-Three of the Charter of the City of Cotabato","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2810"] = {"id":"PH-H2810","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1961/ra_3333_1961.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"通过修订 Iloilo 市宪章，使 Iloilo 省契约登记官兼任 Iloilo 市契约登记官的法案","en":"An Act Making the Register of Deeds of the Province of Iloilo Ex-Officio Register of Deeds for the City of Iloilo, by Amending the Charter of the City of Iloilo","orig":"An Act Making the Register of Deeds of the Province of Iloilo Ex-Officio Register of Deeds for the City of Iloilo, by Amending the Charter of the City of Iloilo"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 3333","issuingBody":"Congress of the Philippines","promulgatedDate":"1961-06-18","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1961/ra_3333_1961.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2810-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby inserted after Section eighty-one, Article X of Commonwealth Act Numbered One hundred and fifty-eight, otherwise known as the Charter of the City of Iloilo, a new section which shall read as follows:\n\"Sec. 81-A. Register of Deeds. -The Register of Deeds of the Province of Iloilo shall be ex-officio Register of Deeds of the City of Iloilo and as such shall receive an additional compensation, to be paid out of the city funds, in the sum of one thousand two hundred pesos per annum.\""}},{"id":"PH-H2810-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1961."}}],"pack":"ph-p39","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Making the Register of Deeds of the Province of Iloilo Ex-Officio Register of Deeds for the City of Iloilo, by Amending the Charter of the City of Iloilo","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2811"] = {"id":"PH-H2811","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1961/ra_3334_1961.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将北三宝颜省 Salug 市镇的政府所在地从 Mucas 村迁至 Salug 村的法案","en":"An Act Transferring the Seat of Government of the Municipality of Salug, Province of Zamboanga del Norte, from the Barrio of Mucas to the Barrio of Salug","orig":"An Act Transferring the Seat of Government of the Municipality of Salug, Province of Zamboanga del Norte, from the Barrio of Mucas to the Barrio of Salug"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 3334","issuingBody":"Congress of the Philippines","promulgatedDate":"1961-06-18","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1961/ra_3334_1961.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2811-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The seat of government of the Municipality of Salug, Province of Zamboanga del Norte, is transferred from the barrio of Mucas to the barrio of Salug."}},{"id":"PH-H2811-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1961."}}],"pack":"ph-p39","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Transferring the Seat of Government of the Municipality of Salug, Province of Zamboanga del Norte, from the Barrio of Mucas to the Barrio of Salug","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2812"] = {"id":"PH-H2812","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1961/ra_3335_1961.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"规定依第685号共和国法在西内格罗斯省Binalbagan市镇设立的菲律宾渔业技术学院分院，改设于Himamaylan与Binalbagan市镇边界的Sirena小区，并为此拨款","en":"An Act Providing that the Branch of the Philippine Institute of Fisheries Technology Authorized Under Republic Act Numbered Six Hundred Eighty-Five to be Established in the Municipality of Binalbagan, Province of Negros Occidental, Shall Instead be Established in the Sitio of Sirena at a Place Touching the Boundary Line Between the Municipality of Himamaylan and the Municipality of Binalbagan, Province of Negros Occidental, and Authorizing the Appropriation of Funds Therefor","orig":"An Act Providing that the Branch of the Philippine Institute of Fisheries Technology Authorized Under Republic Act Numbered Six Hundred Eighty-Five to be Established in the Municipality of Binalbagan, Province of Negros Occidental, Shall Instead be Established in the Sitio of Sirena at a Place Touching the Boundary Line Between the Municipality of Himamaylan and the Municipality of Binalbagan, Province of Negros Occidental, and Authorizing the Appropriation of Funds Therefor"},"level":"law","status":"active","topics":["environment"],"docNumber":"Republic Act No. 3335","issuingBody":"Congress of the Philippines","promulgatedDate":"1961-06-18","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1961/ra_3335_1961.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2812-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The branch of the Philippine Institute of Fisheries Technology authorized under Republic Act Numbered Six hundred eighty-five to be established in the Municipality of Binalbagan, Province of Negros Occidental, shall instead be established in the sitio of Sirena at a place touching the boundary line between the Municipality of Himamaylan and the Municipality of Binalbagan, Province of Negros Occidental."}},{"id":"PH-H2812-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of one hundred fifty thousand pesos is hereby authorized to be appropriated, out of any funds in the National Treasury not otherwise appropriated, for the construction of the building of the said branch of the Philippine Institute of Fisheries Technology in the sitio of Sirena, Province of Negros Occidental, including the purchase of its site. Any sum appropriated in any annual General Appropriations Act for the establishment and maintenance of the branch of the Philippine Institute of Fisheries Technology in the Municipality of Binalbagan, Province of Negros Occidental, is hereby transferred for the establishment and maintenance of the branch of the said Institute at the place hereinabove mentioned."}},{"id":"PH-H2812-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1961."}}],"pack":"ph-p39","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing that the Branch of the Philippine Institute of Fisheries Technology Authorized Under Republic Act Numbered Six Hundred Eighty-Five to be Established in the Municipality of Binalbagan, Province of Negros Occidental, Shall Instead be Established in the Sitio of Sirena at a Place Touching the Boundary Line Between the Municipality of Himamaylan and the Municipality of Binalbagan, Province of Negros Occidental, and Authorizing the Appropriation of Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2813"] = {"id":"PH-H2813","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1961/ra_3336_1961.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"规定 Cotabato 市市政委员会成员的报酬，并为此修订该市宪章第11条的法案","en":"An Act to Provide for the Compensation of the Members of the Municipal Board of the City of Cotabato, Amending for the Purpose Section Eleven of the Charter of the Said City","orig":"An Act to Provide for the Compensation of the Members of the Municipal Board of the City of Cotabato, Amending for the Purpose Section Eleven of the Charter of the Said City"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 3336","issuingBody":"Congress of the Philippines","promulgatedDate":"1961-06-18","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1961/ra_3336_1961.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2813-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section eleven of Republic Act Numbered Twenty-three hundred sixty-four, otherwise known as the \"Charter of the City of Cotabato,\" is amended to read as follows:\n\"Sec. 11. Constitution and organization of the municipal board— Compensation of members thereof.— The municipal board shall be the legislative body of the city and shall be composed of the vice-mayor, who shall be its presiding officer, and eight councilors who shall be elected at-large by popular vote during every election for provincial and municipal officials in conformity with the provisions of the Revised Election Code. The said presiding officer shall vote only in case of tie. In case of sickness, absence, suspension or other temporary disability of any member of the board, or if necessary to maintain a quorum, the President of the Philippines may appoint a temporary substitute belonging to the same political party, who shall possess all the rights and perform all the duties of a member of the board until the return to duty of the regular incumbent.\n\"If any member of the municipal board should be a candidate for office in any election, he shall be disqualified to act with the board in the discharge of the duties conferred upon it relative to election matters, and in such case the other members of the board shall discharge said duties without his assistance, or they may choose some disinterested elector of the city to act with the board in such matters in his stead.\n\"The members of the Municipal Board shall receive the compensation provided in Republic Act Numbered Twenty-two hundred fifty-nine.\""}},{"id":"PH-H2813-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1961."}}],"pack":"ph-p39","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Provide for the Compensation of the Members of the Municipal Board of the City of Cotabato, Amending for the Purpose Section Eleven of the Charter of the Said City","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2814"] = {"id":"PH-H2814","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1961/ra_3337_1961.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"授予Tuguegarao Electric Plant Co.，Inc.在土格加劳市镇范围内电灯、热力与动力系统的特许经营权的法案","en":"An Act Granting the Tuguegarao Electric Plant Co., Inc. a Franchise for an Electric Light, Heat and Power System in the Municipality of Tuguegarao, Province of Cagayan","orig":"An Act Granting the Tuguegarao Electric Plant Co., Inc. a Franchise for an Electric Light, Heat and Power System in the Municipality of Tuguegarao, Province of Cagayan"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 3337","issuingBody":"Congress of the Philippines","promulgatedDate":"1961-06-18","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1961/ra_3337_1961.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2814-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the terms and conditions establish in Act Numbered Thirty-six hundred and thirty-six, as amended by Commonwealth Act Numbered One hundred and thirty-two, and to the provisions of the Constitution, there is granted to the Tuguegarao Electric Plant Co., Inc., for a period of twenty-five years from the approval of this Act, the right, privilege and authority to construct, maintain and operate an electric light, heat and power system in the Municipality of Tuguegarao, Province of Cagayan, for the purpose of generating and distributing electric light, heat and/or power for sale within the limits of the said municipality."}},{"id":"PH-H2814-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In the event that the grantee shall purchase and secure from the National Power Corporation electric heat and power, the National Power Corporation is hereby authorized to negotiate and transact for the benefit and in behalf of the public consumers with reference to rates."}},{"id":"PH-H2814-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"It is expressly provided that in the event the Government should desire to maintain and operate for itself the system and enterprise herein authorized, the grantee shall surrender its franchise and will turn over to the Government all serviceable equipment therein, at cost, less reasonable depreciation."}},{"id":"PH-H2814-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1961."}}],"pack":"ph-p39","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Tuguegarao Electric Plant Co., Inc. a Franchise for an Electric Light, Heat and Power System in the Municipality of Tuguegarao, Province of Cagayan","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2815"] = {"id":"PH-H2815","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1961/ra_3338_1961.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"授权并批准将第1835号共和国法授予 Honorio G. Reyes 先生的临时许可转让给 Enrique M. Orozco 先生的法案","en":"An Act Authorizing and Approving the Transfer of the Temporary Permit Granted to Mr. Honorio G. Reyes by Republic Act Numbered Eighteen Hundred Thirty-Five in Favor of Mr. Enrique M. Orozco","orig":"An Act Authorizing and Approving the Transfer of the Temporary Permit Granted to Mr. Honorio G. Reyes by Republic Act Numbered Eighteen Hundred Thirty-Five in Favor of Mr. Enrique M. Orozco"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 3338","issuingBody":"Congress of the Philippines","promulgatedDate":"1961-06-18","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1961/ra_3338_1961.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2815-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The transfer of the temporary permit granted to Mr. Honorio G. Reyes by Republic Act Numbered Eighteen hundred thirty-five in favor of Mr. Enrique M. Orozco, together with all the rights, privileges and permits that may have been granted to the former is hereby authorized and approved: Provided, That this transfer of temporary permit shall be subject to the same terms and conditions provided under Republic Act Numbered Eighteen hundred thirty-five."}},{"id":"PH-H2815-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 18, 1961."}}],"pack":"ph-p39","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Authorizing and Approving the Transfer of the Temporary Permit Granted to Mr. Honorio G. Reyes by Republic Act Numbered Eighteen Hundred Thirty-Five in Favor of Mr. Enrique M. Orozco","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
